python3 -c 'import itertools,json,sys;K=lambda z:z or sys.exit("FAIL");P=itertools.product;F=(0,1);A=[("sat",tuple(range(3)),0,lambda a,b:min(2,a+b)),("xor",F,0,lambda a,b:a^b),("or",F,0,lambda a,b:a|b),("and",F,1,lambda a,b:a&b),("union",tuple(range(4)),0,lambda a,b:a|b),("func2",tuple(P(F,repeat=2)),(0,1),lambda a,b:(a[b[0]],a[b[1]])),("I",(0,),0,lambda a,b:0)];p=[];j=2;exec("while len(p)<256:\n if all(j%d for d in p if d*d<=j):p.append(j)\n j+=1");v={q:i for i,q in enumerate(p)};E=lambda b:__import__("functools").reduce(lambda n,x:2048*n+p[x],b,1);exec("def D(n):\n K(n>=1)\n b=[]\n while n>1:\n  n,r=divmod(n,2048);K(r in v);b.append(v[r])\n return bytes(b[::-1])");H=C=0;Z=[];exec("for m in A:\n X,e,op=m[1:];K(all(op(e,x)==x==op(x,e) for x in X));K(all(op(x,y) in X and all(op(op(x,y),z)==op(x,op(y,z)) for z in X) for x in X for y in X));L={a:tuple(op(a,x) for x in X) for a in X};K(len(set(L.values()))==len(X));K(all(L[a][X.index(e)]==a for a in X));K(all(tuple(L[a][X.index(op(b,x))] for x in X)==L[op(a,b)] for a in X for b in X));K(L[e]==tuple(X));C+=len(X)\n for a in X:\n  b=json.dumps([m[0],str(a)],ensure_ascii=False).encode();q=E(b);K(D(q)==b);Z.append(q)\n for n in A:\n  Y,d,fn=n[1:]\n  for seq in P(Y,repeat=len(X)):\n   f=dict(zip(X,seq))\n   if f[e]==d and all(f[op(a,b)]==fn(f[a],f[b]) for a in X for b in X):\n    H+=1\n    K(all(f[op(a,x)]==fn(f[a],f[x]) for a in X for x in X))\n");K(len(Z)==len(set(Z))==C);K(all(x!=1-x for x in F));print(json.dumps({"theorem":"faithful Cayley representations of monoids","finite_models":len(A),"embedded_elements":C,"prime_godel_roundtrips":len(Z),"verified_homomorphisms":H,"unit_preserved":True,"recovery":"L_a(e)=a","unrestricted_domains":False,"God_identity_proved":False},sort_keys=True))' "$@"
